const reveal = (
  frame: number,
  start: number,
  end: number,
  easing: (value: number) => number = Easing.out(Easing.cubic),
) =>
  interpolate(frame, [start, end], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing,
  });

const nodeProgress = (frame: number, start: number, end: number) =>
  reveal(frame, start, end, Easing.out(Easing.cubic));

type Point = {
  x: number;
  y: number;
};

type LinkSpec = {
  id: string;
  d: string;
  start: number;
  end: number;
  color: string;
  halo: string;
  width?: number;
};

type NodeSpec = {
  id: string;
  center: Point;
  size: number;
  sprite: number;
  start: number;
  nominal?: number;
  peak?: number;
  end: number;
  accent: string;
  soft: string;
  level: 'root' | 'manager' | 'lead' | 'leaf';
};

