const LEAF_LINKS: LinkSpec[] = LEADS.flatMap((lead, leadIndex) => {
  return [0, 1, 2].map((childIndex) => {
    const leafIndex = leadIndex * 3 + childIndex;
    const leaf = LEAVES[leafIndex];
    const bendX = lead.center.x + (leaf.center.x - lead.center.x) * 0.28;
    const bendY = lead.center.y + (leaf.center.y - lead.center.y) * 0.56;
    return {
      id: `${lead.id}-leaf-${childIndex + 1}`,
      d: `M ${lead.center.x} ${lead.center.y} C ${bendX} ${bendY}, ${leaf.center.x} ${bendY}, ${leaf.center.x} ${leaf.center.y}`,
      start: Math.max(308, leaf.start - 48),
      end: leaf.start - 5,
      color: leaf.accent,
      halo: `${leaf.accent}24`,
      width: 3,
    };
  });
});

