const ConnectorPath: React.FC<{spec: LinkSpec; frame: number}> = ({spec, frame}) => {
  const progress = reveal(frame, spec.start, spec.end, Easing.inOut(Easing.cubic));
  const opacity = reveal(frame, spec.start, spec.start + 8, Easing.linear);
  const width = spec.width ?? 3.5;

  return (
    <g opacity={opacity}>
      <path
        d={spec.d}
        fill="none"
        pathLength={1}
        stroke={spec.halo}
        strokeWidth={width + 9}
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeDasharray={1}
        strokeDashoffset={1 - progress}
      />
      <path
        d={spec.d}
        fill="none"
        pathLength={1}
        stroke="rgba(255,253,248,0.94)"
        strokeWidth={width + 4}
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeDasharray={1}
        strokeDashoffset={1 - progress}
      />
      <path
        d={spec.d}
        fill="none"
        pathLength={1}
        stroke={spec.color}
        strokeWidth={width}
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeDasharray={1}
        strokeDashoffset={1 - progress}
      />
    </g>
  );
};

const ConnectorTree: React.FC<{frame: number}> = ({frame}) => (
  <svg
    width={DESIGN_WIDTH}
    height={DESIGN_HEIGHT}
    viewBox={`0 0 ${DESIGN_WIDTH} ${DESIGN_HEIGHT}`}
    style={{position: 'absolute', inset: 0, overflow: 'visible'}}
  >
    {[...ROOT_LINKS, ...MANAGER_LINKS, ...LEAF_LINKS].map((spec) => (
      <ConnectorPath key={spec.id} spec={spec} frame={frame} />
    ))}
  </svg>
);

const SpritePortrait: React.FC<{sprite: number; diameter: number}> = ({
  sprite,
  diameter,
}) => {
  const column = sprite % 4;
  const row = Math.floor(sprite / 4);
  const sheetSize = diameter * 4;
  const rowHeight = sheetSize / 3;

  return (
    <Img
      src={TEAM_SPRITE}
      style={{
        position: 'absolute',
        width: sheetSize,
        height: sheetSize,
        left: -column * diameter,
        top: -row * rowHeight,
        maxWidth: 'none',
        userSelect: 'none',
      }}
    />
  );
};

const CharacterNode: React.FC<{spec: NodeSpec; frame: number}> = ({spec, frame}) => {
  const progress = nodeProgress(frame, spec.start, spec.end);
  const nominal = spec.nominal ?? spec.start + (spec.end - spec.start) * 0.52;
  const peak = spec.peak ?? spec.start + (spec.end - spec.start) * 0.72;
  const scale = interpolate(frame, [spec.start, nominal, peak, spec.end], [0.12, 1, 1.055, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.out(Easing.cubic),
  });
  const opacity = reveal(frame, spec.start, nominal, Easing.out(Easing.quad));
  const ringThickness = spec.level === 'root' ? 8 : spec.level === 'leaf' ? 3 : 5;
  const inset = spec.level === 'root' ? 12 : spec.level === 'leaf' ? 5 : 8;
  const portraitDiameter = spec.size - inset * 2;
  const shadowStrength = spec.level === 'root' ? 0.16 : spec.level === 'leaf' ? 0.09 : 0.12;

  return (
    <div
      style={{
        position: 'absolute',
        left: spec.center.x - spec.size / 2,
        top: spec.center.y - spec.size / 2,
        width: spec.size,
        height: spec.size,
        opacity,
        transform: `scale(${scale})`,
        transformOrigin: '50% 50%',
        zIndex: spec.level === 'root' ? 5 : spec.level === 'leaf' ? 2 : 4,
      }}
    >
      <div
        style={{
          position: 'absolute',
          inset: -10,
          borderRadius: '50%',
          border: `${ringThickness}px solid ${spec.accent}26`,
          opacity: interpolate(progress, [0, 0.45, 1], [0, 0.85, 0.45], {
            extrapolateLeft: 'clamp',
            extrapolateRight: 'clamp',
          }),
          transform: `scale(${interpolate(progress, [0, 0.72, 1], [0.62, 1.08, 1], {
            extrapolateLeft: 'clamp',
            extrapolateRight: 'clamp',
          })})`,
        }}
      />

      <div
        style={{
          position: 'absolute',
          inset: 0,
          borderRadius: '50%',
          background: `linear-gradient(145deg, ${spec.accent}, ${spec.soft})`,
          border: `${ringThickness}px solid ${COLORS.paper}`,
          boxShadow: `0 16px 36px rgba(37,51,84,${shadowStrength}), 0 0 0 2px ${spec.accent}55`,
        }}
      >
        <div
          style={{
            position: 'absolute',
            left: inset - ringThickness,
            top: inset - ringThickness,
            width: portraitDiameter,
            height: portraitDiameter,
            overflow: 'hidden',
            borderRadius: '50%',
            background: spec.soft,
          }}
        >
          <SpritePortrait sprite={spec.sprite} diameter={portraitDiameter} />
        </div>

        <div
          style={{
            position: 'absolute',
            left: '20%',
            top: '10%',
            width: '30%',
            height: '12%',
            borderRadius: '50%',
            transform: 'rotate(-18deg)',
            background:
              'linear-gradient(90deg, rgba(255,255,255,0.36), rgba(255,255,255,0))',
            pointerEvents: 'none',
          }}
        />
      </div>
    </div>
  );
};

const Hierarchy: React.FC<{frame: number}> = ({frame}) => (
  <>
    <ConnectorTree frame={frame} />
    <CharacterNode spec={ROOT} frame={frame} />
    {MANAGERS.map((spec) => (
      <CharacterNode key={spec.id} spec={spec} frame={frame} />
    ))}
    {LEADS.map((spec) => (
      <CharacterNode key={spec.id} spec={spec} frame={frame} />
    ))}
    {LEAVES.map((spec) => (
      <CharacterNode key={spec.id} spec={spec} frame={frame} />
    ))}
  </>
);

export const Motion: React.FC = () => {
  const rawFrame = useCurrentFrame();
  const frame = Math.min(rawFrame, FINAL_MOTION_FRAME);
  const {width, height} = useVideoConfig();
  const scale = Math.min(width / DESIGN_WIDTH, height / DESIGN_HEIGHT);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: COLORS.ivory,
        overflow: 'hidden',
        alignItems: 'center',
        justifyContent: 'center',
      }}
    >
      <div
        style={{
          position: 'relative',
          width: DESIGN_WIDTH,
          height: DESIGN_HEIGHT,
          flex: 'none',
          transform: `scale(${scale})`,
          transformOrigin: '50% 50%',
          overflow: 'hidden',
        }}
      >
        <PaperBackground />
        <Hierarchy frame={frame} />
      </div>
    </AbsoluteFill>
  );
};
